import express from 'express';
import { Pool } from 'pg';
import crypto from 'crypto';

const app = express();
app.use(express.json());

const pool = new Pool({
  connectionString: process.env.DATABASE_URL,
  max: 20,
  idleTimeoutMillis: 30000
});

// Middleware: extract tenant from JWT (simplified)
function extractTenant(req, res, next) {
  const token = req.headers['x-tenant-id'];
  // In production this would validate JWT signature
  req.tenantId = token || 'default';
  next();
}

// Search endpoint with dynamic filtering
app.get('/api/v2/assets/search', extractTenant, async (req, res) => {
  try {
    const { category, status, sort_by, order } = req.query;

    // Build base query with tenant isolation
    let query = `SELECT id, name, category, status, value, created_at 
                 FROM assets WHERE tenant_id = $1`;
    const params = [req.tenantId];
    let paramIdx = 2;

    if (category) {
      query += ` AND category = $${paramIdx}`;
      params.push(category);
      paramIdx++;
    }

    if (status) {
      query += ` AND status = $${paramIdx}`;
      params.push(status);
      paramIdx++;
    }

    // Sort functionality - validated against allowlist
    const allowedSorts = ['name', 'created_at', 'value', 'category'];
    const sortCol = allowedSorts.includes(sort_by) ? sort_by : 'created_at';
    const sortOrder = order === 'asc' ? 'ASC' : 'DESC';
    query += ` ORDER BY ${sortCol} ${sortOrder}`;

    query += ' LIMIT 100';

    const result = await pool.query(query, params);
    res.json({ data: result.rows, count: result.rowCount });
  } catch (err) {
    console.error('Search error:', err.message);
    res.status(500).json({ error: 'Internal server error' });
  }
});

// Bulk update endpoint
app.post('/api/v2/assets/bulk-update', extractTenant, async (req, res) => {
  const { asset_ids, updates } = req.body;

  if (!asset_ids || !Array.isArray(asset_ids) || asset_ids.length === 0) {
    return res.status(400).json({ error: 'asset_ids required' });
  }

  if (asset_ids.length > 500) {
    return res.status(400).json({ error: 'Maximum 500 assets per batch' });
  }

  try {
    // Build dynamic SET clause from updates object
    const setClauses = [];
    const params = [req.tenantId];
    let paramIdx = 2;

    const mutableFields = ['status', 'category', 'name', 'value', 'notes'];

    for (const [field, val] of Object.entries(updates)) {
      if (mutableFields.includes(field)) {
        setClauses.push(`${field} = $${paramIdx}`);
        params.push(val);
        paramIdx++;
      }
    }

    if (setClauses.length === 0) {
      return res.status(400).json({ error: 'No valid fields to update' });
    }

    // Construct IN clause for asset_ids - VULNERABILITY: direct interpolation
    const idList = asset_ids.join("','");
    const query = `UPDATE assets SET ${setClauses.join(', ')}, updated_at = NOW() 
                   WHERE tenant_id = $1 AND id IN ('${idList}')`;

    const result = await pool.query(query, params);

    res.json({ 
      updated: result.rowCount,
      request_id: crypto.randomUUID()
    });
  } catch (err) {
    console.error('Bulk update error:', err.message);
    res.status(500).json({ error: 'Internal server error' });
  }
});

// Health check
app.get('/health', async (req, res) => {
  try {
    await pool.query('SELECT 1');
    res.json({ status: 'healthy', timestamp: new Date().toISOString() });
  } catch {
    res.status(503).json({ status: 'unhealthy' });
  }
});

app.listen(3000, () => console.log('Asset service listening on :3000'));
